-- Written by hand, as 0013 is: drizzle-kit splits an expression with commas into quoted pieces. The snapshot has them right
CREATE INDEX `idx_roms_name` ON `roms` (`user_id`,`status`,lower(file_name),`id`,`platform`,`disc_group`);--> statement-breakpoint
CREATE INDEX `idx_roms_name_platform` ON `roms` (`user_id`,`status`,`platform`,lower(file_name),`id`,`disc_group`);--> statement-breakpoint
CREATE INDEX `idx_roms_popular` ON `roms` (`user_id`,`status`,CASE WHEN json_extract(raw_game_metadata, '$.launchbox.communityRatingCount') > 0 THEN (json_extract(raw_game_metadata, '$.launchbox.communityRatingCount') * json_extract(raw_game_metadata, '$.launchbox.communityRating') + 350.0) / (json_extract(raw_game_metadata, '$.launchbox.communityRatingCount') + 100) END DESC,lower(file_name),`id`,`platform`,`disc_group`);--> statement-breakpoint
CREATE INDEX `idx_roms_popular_platform` ON `roms` (`user_id`,`status`,`platform`,CASE WHEN json_extract(raw_game_metadata, '$.launchbox.communityRatingCount') > 0 THEN (json_extract(raw_game_metadata, '$.launchbox.communityRatingCount') * json_extract(raw_game_metadata, '$.launchbox.communityRating') + 350.0) / (json_extract(raw_game_metadata, '$.launchbox.communityRatingCount') + 100) END DESC,lower(file_name),`id`,`disc_group`);
